# 2. Переводим в объект Series для удобного расчета скользящего окна
series = pd.Series(raw_coverage)

# 3. Применяем окно длиной 20 и считаем среднее арифметическое.
# min_periods=1 означает, что на краях (где нет 20 позиций) среднее все равно посчитается по доступным точкам
smoothed_data = series.rolling(window=30, min_periods=1).mean()

# 4. Заменяем строгие нули на маленькое ненулевое число (например, 0.05)
# Это сохраняет данные для логарифмирования и убирает log(0)
smoothed_data = smoothed_data.replace(0, 0.01)

# 5. Превращаем результат обратно в стандартный массив NumPy (тип данных станет float64)
data = smoothed_data.to_numpy()

print( len( data ) )

# 1. Находим нижнюю границу степенного хвоста (x_min) и показатель (alpha)
fit = powerlaw.Fit(data, discrete=False)
print("Нижняя граница хвоста (x_min):", fit.xmin)
print("Показатель степени (alpha):", fit.alpha)

# 2. Сравниваем степенной хвост с логнормальным распределением (главный кандидат-конкурент)
R, p_value = fit.distribution_compare('power_law', 'lognormal')
print("Логарифмическое правдоподобие (R):", R) # Если R > 0, то степенное лучше
print("p-value:", p_value) # Если p-value < 0.05, разница статистически значима
